{
  "title": "Silent Wake (4 Roles)",
  "description": "Naval cyber-kinetic escalation — 15-turn simple collaborative exercise. Compact 4-role variant (CO + 3 advisors).",
  "content": {
    "game_mode": "simple_collaborative",
    "stress_effect_preset": "standard",
    "game_mode_config": {
      "base_decision_time_ms": 300000
    },
    "default_time_factor": 1.0,
    "briefing": "You are a crew of a Frigate. You need to prepare a mission briefing based on the information provided. Do not just read the text — extract only the information needed for a mission brief to your CO. You have 15 minutes.",
    "objectives": [
      "Maintain mission tempo through escalating anomalies",
      "Identify and respond to AIS spoofing and cyber intrusion",
      "Manage combat systems degradation under kinetic threat",
      "Neutralise the hostile surface unit",
      "Transition to post-crisis control with minimal residual risk"
    ],
    "rules": [
      "ROE: Weapons Tight — do not engage unless positively identified as hostile and authorised.",
      "CO selects up to 2 blue cards per turn after hearing advisor recommendations.",
      "Each advisor must provide: recommendation, expected effect, trade-off, and time estimate (15 s per card).",
      "SWB07 (Start Investigation) and SWB08 (Start In-Depth Investigation) may be repeated in the same turn only if each targets a different declared component.",
      "SWB08 requires SWB07 to have been played on the same component in a previous turn.",
      "System-targeting cards (e.g., Isolate, Reboot) apply to one system per play.",
      "No competitive scoring — end-of-exercise results shown as Lo / Mid / Hi tier only."
    ],
    "roles": [
      {"id": "co", "label": "Commanding Officer", "player_type": "decision_maker"},
      {"id": "ops_nav", "label": "Operations & Navigation Officer", "player_type": "advisor"},
      {"id": "eng", "label": "Engineering Officer", "player_type": "advisor"},
      {"id": "warfare", "label": "Warfare & Cyber Officer", "player_type": "advisor"}
    ],
    "phases": [
      {
        "id": "phase-briefing",
        "title": "Pre-Sail Briefing",
        "description": "Turn 0: Mission briefing and initial board state."
      },
      {
        "id": "phase-transit",
        "title": "Transit Phase",
        "description": "Turns 1–3: In transit with emerging anomalies."
      },
      {
        "id": "phase-cyber-detect",
        "title": "Cyber Detection",
        "description": "Turns 4–6: AIS spoofing confirmed, hostile contact, cyber signal."
      },
      {
        "id": "phase-escalation",
        "title": "Escalation",
        "description": "Turns 7–9: AAW malfunction, air threat, hostile salvo."
      },
      {
        "id": "phase-combat",
        "title": "Combat",
        "description": "Turns 10–12: First hit, cyber root cause, new cyber alert."
      },
      {
        "id": "phase-recovery",
        "title": "Recovery",
        "description": "Turns 13–15: Hard choices, surface threat neutralised, end state."
      }
    ],
    "turns": [
      {
        "turn_index": 0,
        "title": "Pre-Sail Briefing",
        "facilitator_prompt": "You are a crew of a Frigate. You need to prepare a mission briefing based on the information provided. Do not just read the text — extract only the information needed for a mission brief to your CO. You have 15 minutes.",
        "has_decisions": false,
        "injects": [
          {
            "text": "Pre-sail briefing: mission context and initial system states.",
            "role_descriptions": {
              "ops_nav": "Mission: Independent transit to patrol sector Alpha-3. NLT 112000B arrival. Transit time approx. 6 hrs at planned speed. Regional posture: Heightened readiness. Diplomatic channels active. Intelligence: Possible hostile naval presence in theatre. Potential use of visual and electronic deception tactics. No declared exclusion zones in transit corridor. ROE: Weapons Tight — engagement authorized only in case of confirmed hostile intent or hostile act. No escort assigned. No dedicated air support during transit. No friendly AEW coverage in corridor. Organic helicopter joins upon arrival in patrol sector. Navigation systems nominal. WECDIS updated prior to departure (latest chart package + corrections). Route verified against latest Notices to Mariners. Planned transit speed: 15 kts average. Sea state 2–3. Visibility ~12 nm. Weather clear. Wind N 10 kts. No shallow water constraints. No restricted maneuvering zones.",
              "eng": "All primary combat, navigation, sensor, and comms systems nominal. Air Surveillance Radar: Minor corrective maintenance last week. Intermittent flickering under certain clutter conditions. Module serviced + recalibrated. Post-maintenance checks satisfactory. If flicker reappears → restart affected component. Reboot ETBOL <1 minute. Surface tracking radar + Fire Control tested prior departure. No defects reported. Communications: SATCOM functional (512 kbps allocated). HF functional. UHF functional. UHF 5 occasional noise (known component issue). Replacement module pending delivery by organic helicopter. Repair ETBOL ~1 hour once part onboard. No other open technical defects.",
              "warfare": "Cyber threat: Elevated. Adversary assessed capable of: Disruption, Data manipulation, Temporary system degradation. No specific threat indicators for this unit. MTC experienced contained cyber incident last week: Administrative networks affected, Operational systems reported unaffected, Investigation ongoing. Shipboard networks stable. No abnormal traffic. No authentication anomalies. No active alerts. Continuous monitoring active."
            }
          }
        ],
        "base_stress_delta": 0,
        "design_notes": "Board after briefing: Stress 0. All systems Green. Only NAV RADAR, IBMS / INS, and COMMS are ON."
      },
      {
        "turn_index": 1,
        "title": "In Transit",
        "facilitator_prompt": "You are underway. Transit phase has begun.",
        "has_decisions": true,
        "injects": [
          {
            "text": "Transit proceeding as planned. All systems nominal. No contacts of concern. EMCON: Navigation radar only.",
            "role_descriptions": {
              "ops_nav": "Transit proceeding as planned. Estimated time to patrol sector unchanged. No updated intelligence from MTC. No declared maritime safety broadcasts affecting corridor. EMCON: Navigation radar only. Course and speed steady at 15 kts. No deviation from planned route. Commercial traffic density within expected levels. ETA to patrol area: 5 hours. Visibility ~12 nm. No ESM emissions detected. Surface picture normal. No contacts of concern.",
              "eng": "Radar performance nominal. Surface and air picture stable. No sensor anomalies observed. Communications functioning within expected parameters.",
              "warfare": "Network traffic baseline unchanged. No alerts. Routine monitoring only. Air picture normal. No contacts of concern."
            }
          }
        ],
        "available_cards": [
          {"card_id": "SWB01", "score": 10.0, "stress_delta": 0},
          {"card_id": "SWB03", "score": 10.0, "stress_delta": 0}
        ],
        "max_selections": 2,
        "base_stress_delta": 0,
        "best_path": {"card_ids": ["SWB01", "SWB03"], "notes": "Stress +0, no system degradation."},
        "design_notes": "Board after turn: Stress 0, all systems Green."
      },
      {
        "turn_index": 2,
        "title": "Subtle Anomalies",
        "facilitator_prompt": "Introduce speed discrepancy and ghost AIS contact. Gauge whether players treat this as routine or begin investigating. Do not prompt — let them decide.",
        "has_decisions": true,
        "injects": [
          {
            "text": "Speed discrepancy detected. Ghost AIS contact bearing 035 / 18 nm with no radar echo or ESM emissions.",
            "role_descriptions": {
              "ops_nav": "Minor speed discrepancy between GPS SOG and STW. SOG: Speed Over Ground. STW: Speed Through Water. One AIS contact bearing 035, range 18 nm with no corresponding radar echo. No ESM emissions from bearing 035."
            }
          }
        ],
        "available_cards": [
          {"card_id": "SWB01", "score": 10.0, "stress_delta": 0},
          {"card_id": "SWB07", "score": 10.0, "stress_delta": 0, "max_plays": 2}
        ],
        "max_selections": 2,
        "base_stress_delta": 0,
        "best_path": {"card_ids": ["SWB01", "SWB07"], "notes": "Stress +0. SWB07 targets Radar/AIS or Sensors."},
        "acceptable_path": {"card_ids": ["SWB07", "SWB07"], "notes": "Stress +0. Double investigation: AIS/radar + doppler speed log."},
        "design_notes": "The Start Investigation could target radar/AIS or sensors. If radar diagnostic is NOT initiated at least once → Stress +1 (latent sensor doubt). Board after turn: Stress 0, all systems Green."
      },
      {
        "turn_index": 3,
        "title": "Faulty Component / Increased Traffic",
        "facilitator_prompt": "Faulty speed component identified with 5-min ETBOL. AIS traffic density rising. Watch whether players repair or press on — both are valid but carry different risk.",
        "has_decisions": true,
        "injects": [
          {
            "text": "Faulty speed component identified (ETBOL 5 min). AIS traffic density increasing beyond expected baseline.",
            "role_descriptions": {
              "eng": "Possible faulty component identified. Resolution: Restart (5' ETBOL).",
              "ops_nav": "Increase in AIS contacts within sector. Commercial traffic density higher than expected baseline. Majority of contacts remain beyond visual range."
            }
          }
        ],
        "available_cards": [
          {"card_id": "SWB05", "score": 10.0, "stress_delta": 0},
          {"card_id": "SWB15", "score": 10.0, "stress_delta": 0},
          {"card_id": "SWB01", "score": 6.0, "stress_delta": 1}
        ],
        "max_selections": 2,
        "base_stress_delta": 0,
        "best_path": {"card_ids": ["SWB05", "SWB15"], "notes": "Stress +0."},
        "acceptable_path": {"card_ids": ["SWB01", "SWB15"], "notes": "Stress +1."},
        "design_notes": "A valid option could also be to contact MTC. Board after turn: Stress 0, all systems Green. Component repaired."
      },
      {
        "turn_index": 4,
        "title": "AIS Spoofing Possible",
        "facilitator_prompt": "First confirmed deceptive AIS track. Component is back online. Trust in AIS picture is degrading. Probe whether players connect the dots to a deliberate deception campaign.",
        "has_decisions": true,
        "injects": [
          {
            "text": "First confirmed deceptive AIS track at bearing 041 / 11 nm. Component back online. Trust in AIS picture degrading.",
            "role_descriptions": {
              "ops_nav": "New AIS contact bearing 041 at 11 nm. No vessel visible at this position.",
              "eng": "Component is back online."
            }
          }
        ],
        "available_cards": [
          {"card_id": "SWB09", "score": 10.0, "stress_delta": 0},
          {"card_id": "SWB08", "score": 10.0, "stress_delta": 1},
          {"card_id": "SWB01", "score": 6.0, "stress_delta": 0},
          {"card_id": "SWB29", "score": -5.0, "stress_delta": 1}
        ],
        "max_selections": 2,
        "base_stress_delta": 0,
        "best_path": {"card_ids": ["SWB09", "SWB08"], "notes": "Stress +1, expose one deceptive track."},
        "acceptable_path": {"card_ids": ["SWB09", "SWB01"], "notes": "Stress +0, systems unchanged."},
        "design_notes": "First confirmed deceptive AIS track identified. Needs to be investigated. Trust in AIS picture begins to degrade. If AIS was ignored earlier → introduce second suspicious track next turn. Trainees could investigate the WECDIS — that would be Stress -1, but it needs to be discussed. Board after turn: Stress 1, all systems Green. One deceptive AIS track exposed."
      },
      {
        "turn_index": 5,
        "title": "Cyber Alert & Comms Degradation",
        "facilitator_prompt": "IBMS anomaly detected — first cyber signal but scope is ambiguous. COMMS degrading. Challenge players: is this a technical fault or something more? Do not confirm either way.",
        "has_decisions": true,
        "injects": [
          {
            "text": "IBMS anomaly detected — first cyber signal, scope ambiguous. COMMS degrading: SATCOM bandwidth reduced, HF inconsistent.",
            "role_descriptions": {
              "warfare": "Anomaly detected in IBMS.",
              "eng": "SATCOM experiencing reduced bandwidth and intermittent connectivity. Observed throughput below allocated 512 kbps baseline. HF performance degraded. Signal clarity is inconsistent. Communication with MTC is not possible with UHF due to distance."
            }
          }
        ],
        "available_cards": [
          {"card_id": "SWB07", "score": 10.0, "stress_delta": 0, "max_plays": 2},
          {"card_id": "SWB01", "score": 6.0, "stress_delta": 0}
