        "best_path": {"card_ids": ["SWB07", "SWB07"], "notes": "Stress +1. SWB07 on COMMS + SWB07 on IBMS. COMMS unchanged, reduce escalation chance next turn."},
        "acceptable_path": {"card_ids": ["SWB01", "SWB07"], "notes": "Stress +1. SWB07 on COMMS. COMMS +1 if degraded."},
        "design_notes": "This is the first explicit cyber signal. Still ambiguous in scope. No confirmed impact yet. Communications degradation may be: Environmental, Geographical, Network saturation, Malicious, Coincidental. Cadets should: Move COMMS to Yellow. Move CYBER to Yellow. Board after turn: Stress 2, COMMS Yellow. All others Green."
      },
      {
        "turn_index": 6,
        "title": "Cyber Analysis & Hostile Ship Spotting",
        "facilitator_prompt": "WECDIS-to-INS anomalous data flow detected. Warship contact confirmed. ESM confirms non-commercial emissions. If CO does not select General Quarters (SWB20), it is forced automatically — announce this clearly.",
        "has_decisions": true,
        "injects": [
          {
            "text": "WECDIS → INS anomalous data flow detected. Warship contact confirmed at bearing 052 / 12 nm. ESM confirms non-commercial emissions.",
            "role_descriptions": {
              "warfare": "Analysis indicates anomalous data flow originating from WECDIS towards the INS. INS: Inertial Navigation System (responsible to feed all systems with course and speed considering GPS and inertia sensors). Effects are not yet fully determined. ESM detects non-commercial radar emissions at bearing 052. Emission profile not consistent with merchant vessels.",
              "ops_nav": "New AIS contact bearing 052, range 12 nm. Visual silhouette indicates warship profile."
            }
          }
